import {
  expect,
  expectStatus,
  test,
  uniqueName,
  type APIRequestContext,
  type Document,
  type DocumentKind,
  type Extraction,
  type Vendor,
} from "../../fixtures";

interface ListedDocument extends Document {
  created_at: string;
}

interface QueuedExtraction extends Extraction {
  kind: DocumentKind;
  document_id: string;
  fields: Record<string, { value: string | null; confidence: number }>;
}

interface QueueItem {
  vendor_id: string;
  vendor_name: string;
  extractions: QueuedExtraction[];
}

/** Text a deterministic extraction reads: `Key: Value` lines, with the legal name on the first. */
function w9Text(legalName: string): Buffer {
  return Buffer.from(`Legal Name: ${legalName}\nTax ID: 84-2219067\nBusiness Type: LLC\n`);
}

async function uploadW9(api: APIRequestContext, vendorId: string, legalName: string): Promise<Document> {
  const response = await api.post(`/api/vendors/${vendorId}/documents`, {
    multipart: { kind: "w9", file: { name: "w9.txt", mimeType: "text/plain", buffer: w9Text(legalName) } },
  });
  return expectStatus<Document>(response, 201);
}

async function expectExtracted(api: APIRequestContext, documentId: string) {
  await expect
    .poll(async () => (await expectStatus<Document>(await api.get(`/api/documents/${documentId}`), 200)).status, {
      message: "document extraction finishes",
      timeout: 30_000,
    })
    .toBe("extracted");
}

test("a re-uploaded document is the one that gets reviewed", { tag: "@LIF-01" }, async ({ apiAs, factory }) => {
  // Arrange: a draft vendor with insurance and contract documents, extracted.
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await factory.vendor({ name: uniqueName("Lifecycle LIF-01") });
  const insurance = await factory.upload(vendor.id, "insurance_certificate");
  const contract = await factory.upload(vendor.id, "contract");
  await expectExtracted(member, insurance.id);
  await expectExtracted(member, contract.id);

  // Arrange: two W9 uploads, each extracted, the second replacing the first's legal name.
  const first = await uploadW9(member, vendor.id, "First Name LLC");
  await expectExtracted(member, first.id);
  const second = await uploadW9(member, vendor.id, "Second Name LLC");
  await expectExtracted(member, second.id);

  // Act: submit the vendor, then the reviewer opens the queue.
  const submitted = await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  expect(submitted.status).toBe("in_review");
  const queue = await expectStatus<QueueItem[]>(await reviewer.get("/api/review-queue"), 200);

  // Assert: the queue's W9 extraction is the second upload, showing its legal name.
  const item = queue.find((i) => i.vendor_id === vendor.id);
  expect(item, "vendor appears in the review queue").toBeDefined();
  const w9Extractions = item?.extractions.filter((e) => e.kind === "w9") ?? [];
  expect(w9Extractions).toHaveLength(1);
  expect(w9Extractions[0].document_id).toBe(second.id);
  expect(w9Extractions[0].fields.legal_name.value).toBe("Second Name LLC");

  // Assert: the vendor's documents list both W9 uploads, oldest first.
  const listed = await expectStatus<ListedDocument[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
  expect(listed.map((d) => d.kind).sort()).toEqual(["contract", "insurance_certificate", "w9", "w9"]);
  expect(listed.filter((d) => d.kind === "w9").map((d) => d.id)).toEqual([first.id, second.id]);
  const createdAt = listed.map((d) => Date.parse(d.created_at));
  expect(createdAt).toEqual([...createdAt].sort((a, b) => a - b));
});
